-- 00118 · استكمال عزل القاطع في لوحة الكراج والتقارير والصيانة والإشعارات.

alter table public.garage_vehicles add column garage_parent_sector text;
update public.garage_vehicles v set garage_parent_sector=s.parent_sector from public.sectors s where s.id=v.sector_id;
alter table public.garage_vehicles alter column garage_parent_sector set not null;
alter table public.garage_vehicles add constraint garage_vehicle_parent_sector_check check(garage_parent_sector in('karrada','zaafaraniya'));
create or replace function app.set_vehicle_garage_parent()returns trigger language plpgsql security definer set search_path=public as $$begin if tg_op='INSERT'and new.garage_parent_sector is null then select parent_sector into new.garage_parent_sector from public.sectors where id=new.sector_id;end if;return new;end$$;
create trigger trg_set_vehicle_garage_parent before insert on public.garage_vehicles for each row execute function app.set_vehicle_garage_parent();

create or replace function app.garage_vehicle_allowed(p_vehicle_id uuid)returns boolean language sql stable security definer set search_path=public,app as $$select case when app.has_role(array['ops_room','super_admin'])then true when app.has_role(array['central_garage_officer'])then exists(select 1 from public.garage_vehicles v join public.garage_user_profiles gp on gp.user_id=auth.uid()where v.id=p_vehicle_id and v.garage_parent_sector=gp.parent_sector)else false end$$;

create or replace function app.garage_sector_allowed(p_sector_id smallint)returns boolean language sql stable security definer set search_path=public,app as $$select case when app.has_role(array['ops_room','super_admin'])then true when app.has_role(array['central_garage_officer'])then exists(select 1 from public.sectors s join public.garage_user_profiles gp on gp.user_id=auth.uid()where s.id=p_sector_id and s.parent_sector=gp.parent_sector)else false end$$;
revoke all on function app.garage_sector_allowed(smallint)from public,anon;
grant execute on function app.garage_sector_allowed(smallint)to authenticated;


-- قائمة الآليات تعتمد الكراج الثابت للآلية، لا موقع أحد الشفتات.
create or replace function public.garage_search_vehicles(p_search text default null,p_sector_id smallint default null,p_shift text default null,p_limit integer default 48,p_offset integer default 0,p_archived boolean default false)
returns table(id uuid,vehicle_name text,db_number text,plate_number text,chassis_number text,image_path text,vehicle_category text,ownership_type text,lessor_name text,rental_contract_no text,rental_start_date date,rental_end_date date,model_year smallint,vehicle_color text,specifications text,shift text,driver_name text,sector_id smallint,area_name text,parent_sector text,created_at timestamptz,updated_at timestamptz,archived_at timestamptz,archived_by uuid,archive_reason text,total_count bigint)
language plpgsql stable security definer set search_path=public,app as $$declare q text:=trim(coalesce(p_search,''));garage_parent text:=app.current_garage_parent_sector();begin if auth.uid()is null or not app.has_role(array['central_garage_officer','ops_room','super_admin'])then raise exception'GARAGE_FORBIDDEN';end if;if app.has_role(array['central_garage_officer'])and not app.has_role(array['ops_room','super_admin'])and garage_parent is null then raise exception'GARAGE_PROFILE_NOT_CONFIGURED';end if;if p_shift is not null and p_shift not in('morning','evening','night')then raise exception'GARAGE_SHIFT_INVALID';end if;if p_limit<1 or p_limit>100 or p_offset<0 then raise exception'GARAGE_PAGINATION_INVALID';end if;return query select v.id,v.vehicle_name,v.db_number,v.plate_number,v.chassis_number,v.image_path,v.vehicle_category,v.ownership_type,v.lessor_name,v.rental_contract_no,v.rental_start_date,v.rental_end_date,v.model_year,v.vehicle_color,v.specifications,v.shift,v.driver_name,v.sector_id,s.name,v.garage_parent_sector,v.created_at,v.updated_at,v.archived_at,v.archived_by,v.archive_reason,count(*)over()from public.garage_vehicles v join public.sectors s on s.id=v.sector_id where(case when p_archived then v.archived_at is not null else v.archived_at is null end)and(garage_parent is null or app.has_role(array['ops_room','super_admin'])or v.garage_parent_sector=garage_parent)and(p_sector_id is null or v.sector_id=p_sector_id)and(p_shift is null or v.shift=p_shift)and(q=''or v.db_number ilike'%'||q||'%'or v.vehicle_name ilike'%'||q||'%'or v.driver_name ilike'%'||q||'%'or v.plate_number ilike'%'||q||'%'or v.chassis_number ilike'%'||q||'%'or v.lessor_name ilike'%'||q||'%')order by case when p_archived then v.archived_at else v.created_at end desc limit p_limit offset p_offset;end$$;

-- إسناد شفت مستقل لا يغيّر القاطع الثابت أو بيانات الآلية الرئيسية.
create or replace function public.garage_set_vehicle_shift_assignment(p_vehicle_id uuid,p_shift text,p_driver_name text,p_sector_id smallint,p_reason text)
returns public.garage_vehicle_shift_assignments language plpgsql security definer set search_path=public,app as $$declare u uuid:=app.require_fleet_master_actor();r public.garage_vehicle_shift_assignments;begin if p_shift not in('morning','evening','night')or length(trim(coalesce(p_driver_name,'')))<2 or length(trim(coalesce(p_reason,'')))<3 then raise exception'GARAGE_SHIFT_ASSIGNMENT_INVALID';end if;if not exists(select 1 from public.garage_vehicles where id=p_vehicle_id and archived_at is null)then raise exception'GARAGE_VEHICLE_NOT_FOUND';end if;if not exists(select 1 from public.sectors where id=p_sector_id)then raise exception'GARAGE_AREA_INVALID';end if;perform pg_advisory_xact_lock(hashtextextended(p_vehicle_id::text||p_shift,0));if exists(select 1 from public.garage_departures where vehicle_id=p_vehicle_id and shift=p_shift and returned_at is null)then raise exception'GARAGE_SHIFT_IN_FIELD';end if;update public.garage_vehicle_shift_assignments set ends_at=now(),change_reason=trim(p_reason)where vehicle_id=p_vehicle_id and shift=p_shift and ends_at is null;insert into public.garage_vehicle_shift_assignments(vehicle_id,shift,driver_name,sector_id,change_reason,created_by)values(p_vehicle_id,p_shift,trim(p_driver_name),p_sector_id,trim(p_reason),u)returning*into r;return r;end$$;

create or replace function public.garage_maintenance_coordination()returns table(case_id uuid,departure_id uuid,vehicle_name text,db_number text,vehicle_category text,driver_name text,sector_name text,manager_name text,fault_type text,priority text,dispatch_policy text,decision_status text,reported_at timestamptz,decision_notes text)language plpgsql stable security definer set search_path=public,app as $$begin perform app.require_garage_actor();return query select c.id,c.departure_id,v.vehicle_name,v.db_number,v.vehicle_category,d.driver_name,s.name,d.recipient_manager_name,c.fault_type,c.priority,c.dispatch_policy,c.garage_decision_status,c.reported_at,c.garage_decision_notes from public.vehicle_maintenance_cases c join public.garage_departures d on d.id=c.departure_id join public.garage_vehicles v on v.id=c.vehicle_id join public.sectors s on s.id=d.sector_id where app.garage_vehicle_allowed(v.id)and c.garage_decision_status in('awaiting_ack','awaiting_approval','acknowledged','approved','rejected')and c.reported_at>now()-interval'30 days'order by c.garage_decision_status in('awaiting_ack','awaiting_approval')desc,c.reported_at desc;end$$;


-- تنبيهات الوصول والمغادرة النهائية تصل إلى كراج القاطع المعني فقط.
create or replace function app.notify_maintenance_terminal_transitions()returns trigger
language plpgsql security definer set search_path=public,app as $$declare v public.garage_vehicles;begin
 select*into v from public.garage_vehicles where id=new.vehicle_id;
 if old.arrived_at is null and new.arrived_at is not null then
  insert into public.notifications(user_id,title,body,type,category,priority,link,entity_type,entity_id,action_label,dedupe_key)
  select distinct ur.user_id,'أكدت الصيانة وصول الآلية',format('%s · DB %s وصلت وبدأت المتابعة',v.vehicle_name,v.db_number),'success','maintenance','high','/central-garage/maintenance-coordination','maintenance_case',new.id,'فتح التسلسل الزمني','maintenance_case:'||new.id::text||':arrived:garage'
  from public.user_roles ur where ur.role='super_admin'or(ur.role='central_garage_officer'and exists(select 1 from public.garage_user_profiles gp where gp.user_id=ur.user_id and gp.parent_sector=v.garage_parent_sector))
  on conflict(user_id,dedupe_key)where dedupe_key is not null do nothing;
 end if;
 if old.departed_maintenance_at is null and new.departed_maintenance_at is not null and new.status='to_work'then
  insert into public.notifications(user_id,title,body,type,category,priority,link,entity_type,entity_id,action_label,dedupe_key)
  select distinct ur.user_id,'الآلية عائدة من الصيانة إلى العمل',format('%s · DB %s غادرت الصيانة بعد اعتماد الجاهزية',v.vehicle_name,v.db_number),'info','maintenance','high','/central-garage/maintenance-coordination','maintenance_case',new.id,'فتح التسلسل الزمني','maintenance_case:'||new.id::text||':departed-to-work:garage'
  from public.user_roles ur where ur.role='super_admin'or(ur.role='central_garage_officer'and exists(select 1 from public.garage_user_profiles gp where gp.user_id=ur.user_id and gp.parent_sector=v.garage_parent_sector))
  on conflict(user_id,dedupe_key)where dedupe_key is not null do nothing;
 end if;
 if old.completed_at is null and new.completed_at is not null and new.status='returned_to_work'then
  insert into public.notifications(user_id,title,body,type,category,priority,link,entity_type,entity_id,action_label,dedupe_key)
  select distinct x.user_id,'اكتملت عودة الآلية إلى العمل',format('%s · DB %s أكد مسؤول القسم وصولها الفعلي',v.vehicle_name,v.db_number),'success','maintenance','high',x.link,'maintenance_case',new.id,'فتح التسلسل الزمني','maintenance_case:'||new.id::text||':returned-to-work:'||x.audience
  from(
   select ur.user_id,'/central-garage/maintenance-coordination'::text link,'garage'::text audience from public.user_roles ur where ur.role='super_admin'or(ur.role='central_garage_officer'and exists(select 1 from public.garage_user_profiles gp where gp.user_id=ur.user_id and gp.parent_sector=v.garage_parent_sector))
   union all select ur.user_id,'/maintenance/vehicle-cases','maintenance'from public.user_roles ur where ur.role='maintenance'
  )x on conflict(user_id,dedupe_key)where dedupe_key is not null do nothing;
 elsif old.completed_at is null and new.completed_at is not null and new.status='closed_at_garage'then
  insert into public.notifications(user_id,title,body,type,category,priority,link,entity_type,entity_id,action_label,dedupe_key)
  select distinct ur.user_id,'اكتمل وصول الآلية إلى الكراج',format('%s · DB %s أكد الكراج وصولها الفعلي وإغلاق الحالة',v.vehicle_name,v.db_number),'success','maintenance','high','/maintenance/vehicle-cases','maintenance_case',new.id,'فتح التسلسل الزمني','maintenance_case:'||new.id::text||':closed-at-garage:maintenance'
  from public.user_roles ur where ur.role='maintenance'
  on conflict(user_id,dedupe_key)where dedupe_key is not null do nothing;
 end if;return new;
end$$;

create or replace function app.notify_garage_new_maintenance_case()returns trigger language plpgsql security definer set search_path=public,app as $$declare v public.garage_vehicles;pol public.notification_workflow_policies;parent text;begin select*into v from public.garage_vehicles where id=new.vehicle_id;parent:=v.garage_parent_sector;pol:=app.effective_notification_policy('maintenance_dispatch',(select sector_id from public.garage_departures where id=new.departure_id),v.vehicle_category);insert into public.notifications(user_id,title,body,type,category,priority,link,entity_type,entity_id,action_label,dedupe_key,in_app_visible,push_allowed,sound_allowed)select distinct ur.user_id,case new.garage_decision_status when'awaiting_approval'then'طلب موافقة لإرسال آلية إلى الصيانة'when'awaiting_ack'then'آلية إلى الصيانة تحتاج تأكيد الاستلام'else'بلاغ آلية متجهة إلى الصيانة'end,format('%s · DB %s — %s',v.vehicle_name,v.db_number,new.fault_type),case when new.priority='critical'then'error'else'warning'end,'maintenance',case when new.priority='critical'then'critical'when new.priority='urgent'then'high'else'normal'end,'/central-garage/maintenance-coordination','maintenance_case',new.id,case new.garage_decision_status when'awaiting_approval'then'مراجعة الطلب'when'awaiting_ack'then'تأكيد الاستلام'else'فتح التفاصيل'end,'maintenance_case:'||new.id::text||':garage',coalesce(pol.in_app_enabled,true),coalesce(pol.push_enabled,true),coalesce(pol.sound_enabled,true)from public.user_roles ur where ur.role=any(coalesce(pol.recipient_roles,array['central_garage_officer']))and(ur.role<>'central_garage_officer'or exists(select 1 from public.garage_user_profiles gp where gp.user_id=ur.user_id and gp.parent_sector=parent))on conflict(user_id,dedupe_key)where dedupe_key is not null do nothing;return new;end$$;

create or replace function app.require_garage_case_access(p_case_id uuid)returns void language plpgsql stable security definer set search_path=public,app as $$declare vid uuid;begin select vehicle_id into vid from public.vehicle_maintenance_cases where id=p_case_id;if vid is null then raise exception'MAINTENANCE_CASE_NOT_FOUND';end if;if app.has_role(array['central_garage_officer'])and not app.garage_vehicle_allowed(vid)then raise exception'GARAGE_VEHICLE_SCOPE_FORBIDDEN';end if;end$$;
revoke all on function app.require_garage_case_access(uuid)from public,anon,authenticated;

create or replace function public.garage_decide_maintenance_dispatch(p_case_id uuid,p_decision text,p_notes text default null)returns public.vehicle_maintenance_cases language plpgsql security definer set search_path=public,app as $$declare u uuid:=app.require_garage_actor();c public.vehicle_maintenance_cases;d public.garage_departures;v public.garage_vehicles;l public.vehicle_trip_legs;begin perform app.require_garage_case_access(p_case_id);if p_decision not in('acknowledge','approve','reject')or length(coalesce(p_notes,''))>500 then raise exception'MAINTENANCE_DECISION_INVALID';end if;select*into c from public.vehicle_maintenance_cases where id=p_case_id for update;select*into d from public.garage_departures where id=c.departure_id for update;select*into v from public.garage_vehicles where id=c.vehicle_id;if p_decision='acknowledge'then if c.garage_decision_status<>'awaiting_ack'then raise exception'MAINTENANCE_ACK_NOT_ALLOWED';end if;update public.vehicle_maintenance_cases set garage_decision_status='acknowledged',garage_decided_at=now(),garage_decided_by=u,garage_decision_notes=nullif(trim(coalesce(p_notes,'')),'')where id=c.id returning*into c;elsif p_decision='approve'then if c.garage_decision_status<>'awaiting_approval'or exists(select 1 from public.vehicle_trip_legs where departure_id=d.id and arrived_at is null)then raise exception'MAINTENANCE_APPROVAL_NOT_ALLOWED';end if;insert into public.vehicle_trip_legs(departure_id,sequence_no,origin_type,destination_type,departed_by,departure_notes)values(d.id,app.next_trip_leg_sequence(d.id),'work_site','maintenance',u,'اعتمد الكراج حركة الصيانة')returning*into l;update public.vehicle_maintenance_cases set garage_decision_status='approved',garage_decided_at=now(),garage_decided_by=u,garage_decision_notes=nullif(trim(coalesce(p_notes,'')),'')where id=c.id returning*into c;insert into public.notifications(user_id,title,body,type,category,priority,link,entity_type,entity_id,dedupe_key)select ur.user_id,'اعتمد الكراج إرسال الآلية إلى الصيانة',format('الآلية DB %s أصبحت في الطريق إلى الصيانة',v.db_number),'success','maintenance','high','/maintenance/vehicle-cases','maintenance_case',c.id,'maintenance_case:'||c.id::text||':approved-maintenance'from public.user_roles ur where ur.role='maintenance'on conflict(user_id,dedupe_key)where dedupe_key is not null do nothing;else if c.garage_decision_status<>'awaiting_approval'then raise exception'MAINTENANCE_REJECTION_NOT_ALLOWED';end if;if length(trim(coalesce(p_notes,'')))<3 then raise exception'MAINTENANCE_REJECTION_REASON_REQUIRED';end if;update public.vehicle_maintenance_cases set garage_decision_status='rejected',garage_decided_at=now(),garage_decided_by=u,garage_decision_notes=trim(p_notes),status='cancelled',completed_at=now(),updated_at=now()where id=c.id returning*into c;end if;insert into public.notifications(user_id,title,body,type,category,priority,link,entity_type,entity_id,dedupe_key)values(c.manager_id,case p_decision when'acknowledge'then'استلم الكراج بلاغ الصيانة'when'approve'then'وافق الكراج على حركة الصيانة'else'لم يعتمد الكراج حركة الصيانة'end,case when p_decision='reject'then coalesce(c.garage_decision_notes,'راجع الكراج')else format('الآلية DB %s — تم تحديث التنسيق مع الكراج',v.db_number)end,case when p_decision='reject'then'error'else'success'end,'maintenance',case when p_decision='reject'then'high'else'normal'end,'/manager/vehicle-trips','maintenance_case',c.id,'maintenance_case:'||c.id::text||':decision');return c;end$$;

-- إعادة تعريف لوحة المؤشرات مع فرض نطاق الكراج داخل كل تجميع.
create or replace function public.garage_dashboard_summary(p_from date default null,p_to date default null,p_sector_id smallint default null,p_fuel_type text default null)
returns jsonb language plpgsql stable security definer set search_path=public,app as $$
declare v_from date:=coalesce(p_from,timezone('Asia/Baghdad',now())::date-29);v_to date:=coalesce(p_to,timezone('Asia/Baghdad',now())::date);v_result jsonb;
begin
  perform app.require_garage_actor();
  if p_sector_id is not null and not app.garage_sector_allowed(p_sector_id) then raise exception 'GARAGE_SECTOR_SCOPE_FORBIDDEN'; end if;
  if v_from>v_to or v_to-v_from>366 then raise exception 'GARAGE_DATE_RANGE_INVALID'; end if;
  if p_sector_id is not null and not exists(select 1 from public.sectors where id=p_sector_id) then raise exception 'GARAGE_SECTOR_INVALID'; end if;
  if p_fuel_type is not null and p_fuel_type not in ('gas_oil','hydraulic','grease','c_oil') then raise exception 'GARAGE_FUEL_TYPE_INVALID'; end if;
  select jsonb_build_object(
    'vehiclesTotal',(select count(*) from public.garage_vehicles v where v.archived_at is null and app.garage_vehicle_allowed(v.id) and (p_sector_id is null or v.sector_id=p_sector_id)),
    'driversTotal',(select count(distinct a.driver_name) from public.garage_driver_assignments a join public.garage_vehicles v on v.id=a.vehicle_id where a.ends_at is null and v.archived_at is null and app.garage_vehicle_allowed(v.id) and (p_sector_id is null or a.sector_id=p_sector_id)),
    'dispatchesTotal',(select count(*) from public.garage_departures d where timezone('Asia/Baghdad',d.departed_at)::date between v_from and v_to and app.garage_vehicle_allowed(d.vehicle_id) and (p_sector_id is null or d.sector_id=p_sector_id)),
    'vehiclesByShift',(select coalesce(jsonb_object_agg(shift,total),'{}') from(select v.shift,count(*) total from public.garage_vehicles v where v.archived_at is null and app.garage_vehicle_allowed(v.id) and (p_sector_id is null or v.sector_id=p_sector_id) group by v.shift)s),
    'vehiclesByArea',(select coalesce(jsonb_agg(jsonb_build_object('sectorId',s.id,'sector',s.parent_sector,'area',s.name,'total',coalesce(v.total,0)) order by s.sort),'[]') from public.sectors s left join(select sector_id,count(*) total from public.garage_vehicles where archived_at is null group by sector_id)v on v.sector_id=s.id where app.garage_sector_allowed(s.id) and (p_sector_id is null or s.id=p_sector_id)),
    'tankStock',(select coalesce(jsonb_agg(jsonb_build_object('id',id,'fuelType',fuel_type,'name',tank_name,'unit',unit,'capacity',capacity,'quantity',current_quantity,'percent',round(current_quantity*100/nullif(capacity,0),2),'lowStock',current_quantity<=low_stock_threshold) order by fuel_type,tank_name),'[]') from public.garage_tanks where archived_at is null and (p_fuel_type is null or fuel_type=p_fuel_type)),
    'fuelUnits',(select coalesce(jsonb_object_agg(fuel_type,unit),'{}') from(select distinct on(fuel_type) fuel_type,unit from public.garage_tanks order by fuel_type,created_at desc)x),
    'consumptionByType',(select coalesce(jsonb_object_agg(fuel_type,total),'{}') from(select t.fuel_type,sum(-m.quantity) total from public.garage_inventory_movements m join public.garage_tanks t on t.id=m.tank_id join public.garage_vehicles v on v.id=m.vehicle_id where m.movement_type='vehicle_fill' and app.garage_vehicle_allowed(v.id) and timezone('Asia/Baghdad',m.created_at)::date between v_from and v_to and (p_sector_id is null or v.sector_id=p_sector_id) and (p_fuel_type is null or t.fuel_type=p_fuel_type) group by t.fuel_type)x),
    'consumptionByUnit',(select coalesce(jsonb_object_agg(unit,total),'{}') from(select t.unit,sum(-m.quantity) total from public.garage_inventory_movements m join public.garage_tanks t on t.id=m.tank_id join public.garage_vehicles v on v.id=m.vehicle_id where m.movement_type='vehicle_fill' and app.garage_vehicle_allowed(v.id) and timezone('Asia/Baghdad',m.created_at)::date between v_from and v_to and (p_sector_id is null or v.sector_id=p_sector_id) and (p_fuel_type is null or t.fuel_type=p_fuel_type) group by t.unit)x),
    'dailyConsumption',case when p_fuel_type is not null and (select count(distinct unit) from public.garage_tanks where archived_at is null and fuel_type=p_fuel_type)=1 then (select coalesce(jsonb_agg(jsonb_build_object('date',d.day,'quantity',coalesce(x.total,0)) order by d.day),'[]') from generate_series(v_from,v_to,'1 day'::interval)d(day) left join(select timezone('Asia/Baghdad',m.created_at)::date movement_date,sum(-m.quantity) total from public.garage_inventory_movements m join public.garage_tanks t on t.id=m.tank_id join public.garage_vehicles v on v.id=m.vehicle_id where m.movement_type='vehicle_fill' and app.garage_vehicle_allowed(v.id) and timezone('Asia/Baghdad',m.created_at)::date between v_from and v_to and (p_sector_id is null or v.sector_id=p_sector_id) and (p_fuel_type is null or t.fuel_type=p_fuel_type) group by 1)x on x.movement_date=d.day::date) else '[]'::jsonb end,
    'monthlyConsumption',case when p_fuel_type is not null and (select count(distinct unit) from public.garage_tanks where archived_at is null and fuel_type=p_fuel_type)=1 then (select coalesce(jsonb_agg(jsonb_build_object('month',x.month_key,'quantity',x.total) order by x.month_key),'[]') from(select to_char(date_trunc('month',timezone('Asia/Baghdad',m.created_at)),'YYYY-MM') month_key,sum(-m.quantity) total from public.garage_inventory_movements m join public.garage_tanks t on t.id=m.tank_id join public.garage_vehicles v on v.id=m.vehicle_id where m.movement_type='vehicle_fill' and app.garage_vehicle_allowed(v.id) and timezone('Asia/Baghdad',m.created_at)::date between v_from and v_to and (p_sector_id is null or v.sector_id=p_sector_id) and (p_fuel_type is null or t.fuel_type=p_fuel_type) group by 1)x) else '[]'::jsonb end,
    'topConsumers',(select coalesce(jsonb_agg(to_jsonb(x) order by x.quantity desc),'[]') from(select v.id "vehicleId",v.vehicle_name "vehicleName",v.db_number "dbNumber",t.unit,sum(-m.quantity) quantity from public.garage_inventory_movements m join public.garage_tanks t on t.id=m.tank_id join public.garage_vehicles v on v.id=m.vehicle_id where m.movement_type='vehicle_fill' and app.garage_vehicle_allowed(v.id) and timezone('Asia/Baghdad',m.created_at)::date between v_from and v_to and (p_sector_id is null or v.sector_id=p_sector_id) and (p_fuel_type is null or t.fuel_type=p_fuel_type) group by v.id,v.vehicle_name,v.db_number,t.unit order by quantity desc limit 5)x),
    'recentFills',(select coalesce(jsonb_agg(to_jsonb(x) order by x."createdAt" desc),'[]') from(select m.id,v.vehicle_name "vehicleName",v.db_number "dbNumber",t.tank_name "tankName",t.fuel_type "fuelType",t.unit,-m.quantity quantity,m.next_refill_date "nextRefillDate",m.created_at "createdAt" from public.garage_inventory_movements m join public.garage_tanks t on t.id=m.tank_id join public.garage_vehicles v on v.id=m.vehicle_id where m.movement_type='vehicle_fill' and app.garage_vehicle_allowed(v.id) and (p_sector_id is null or v.sector_id=p_sector_id) and (p_fuel_type is null or t.fuel_type=p_fuel_type) order by m.created_at desc limit 8)x),
    'pendingZeroItems',(select coalesce(jsonb_agg(to_jsonb(x) order by x."requestedAt" desc),'[]') from(select r.id,t.tank_name "tankName",t.fuel_type "fuelType",t.unit,r.requested_quantity "requestedQuantity",r.reason,r.requested_at "requestedAt" from public.garage_tank_zero_requests r join public.garage_tanks t on t.id=r.tank_id where r.status='pending' and (p_fuel_type is null or t.fuel_type=p_fuel_type) order by r.requested_at desc limit 8)x),
    'pendingZeroRequests',(select count(*) from public.garage_tank_zero_requests r join public.garage_tanks t on t.id=r.tank_id where r.status='pending' and (p_fuel_type is null or t.fuel_type=p_fuel_type)),
    'from',v_from,'to',v_to,'sectorId',p_sector_id,'fuelType',p_fuel_type
  ) into v_result;
  return v_result;
end$$;

-- إعادة تعريف التقرير مع منع تمرير معرفات آليات القاطع الآخر وتصفية الصفوف.
create or replace function public.garage_consumption_report(
  p_from date default null,p_to date default null,p_sector_id smallint default null,
  p_fuel_type text default null,p_tank_id uuid default null,p_vehicle_id uuid default null,
  p_vehicle_ids uuid[] default null,p_movement_type text default null,p_limit integer default 50,p_offset integer default 0
) returns jsonb language plpgsql stable security definer set search_path=public,app as $$
declare v_from date:=coalesce(p_from,timezone('Asia/Baghdad',now())::date-29);v_to date:=coalesce(p_to,timezone('Asia/Baghdad',now())::date);v_result jsonb;v_vehicle_ids uuid[];
begin
  perform app.require_garage_actor();
  v_vehicle_ids:=case when p_vehicle_ids is null then null else array(select distinct x from unnest(p_vehicle_ids) x) end;
  if p_sector_id is not null and not app.garage_sector_allowed(p_sector_id) then raise exception 'GARAGE_SECTOR_SCOPE_FORBIDDEN'; end if;
  if p_vehicle_id is not null and not app.garage_vehicle_allowed(p_vehicle_id) then raise exception 'GARAGE_VEHICLE_SCOPE_FORBIDDEN'; end if;
  if v_vehicle_ids is not null and exists(select 1 from unnest(v_vehicle_ids) x where not app.garage_vehicle_allowed(x)) then raise exception 'GARAGE_VEHICLE_SCOPE_FORBIDDEN'; end if;
  if v_from>v_to or v_to-v_from>366 then raise exception 'GARAGE_REPORT_DATE_RANGE_INVALID'; end if;
  if p_limit<1 or p_limit>100 or p_offset<0 then raise exception 'GARAGE_REPORT_PAGINATION_INVALID'; end if;
  if cardinality(v_vehicle_ids)>50 or array_position(v_vehicle_ids,null) is not null then raise exception 'GARAGE_REPORT_VEHICLES_INVALID'; end if;
  if p_vehicle_id is not null and v_vehicle_ids is not null then raise exception 'GARAGE_REPORT_VEHICLE_FILTER_CONFLICT'; end if;
  if v_vehicle_ids is not null and exists(select 1 from unnest(v_vehicle_ids) x left join public.garage_vehicles v on v.id=x where v.id is null) then raise exception 'GARAGE_REPORT_VEHICLE_NOT_FOUND'; end if;
  if p_fuel_type is not null and p_fuel_type not in ('gas_oil','hydraulic','grease','c_oil') then raise exception 'GARAGE_FUEL_TYPE_INVALID'; end if;
  if p_movement_type is not null and p_movement_type not in ('stock_in','vehicle_fill','approved_reset') then raise exception 'GARAGE_MOVEMENT_TYPE_INVALID'; end if;
  if p_sector_id is not null and not exists(select 1 from public.sectors where id=p_sector_id) then raise exception 'GARAGE_SECTOR_INVALID'; end if;
  with filtered as materialized (
    select m.id,m.tank_id,m.vehicle_id,m.movement_type,m.quantity,m.quantity_before,m.quantity_after,
      m.next_refill_date,m.notes,m.actor_id,coalesce(nullif(u.raw_user_meta_data->>'full_name',''),u.email,m.actor_id::text) actor_name,m.created_at,t.tank_name,t.fuel_type,t.unit,
      v.vehicle_name,v.db_number,v.sector_id,s.name area_name,s.parent_sector
    from public.garage_inventory_movements m join public.garage_tanks t on t.id=m.tank_id
    left join auth.users u on u.id=m.actor_id left join public.garage_vehicles v on v.id=m.vehicle_id left join public.sectors s on s.id=v.sector_id
    where timezone('Asia/Baghdad',m.created_at)::date between v_from and v_to
      and (m.vehicle_id is null or app.garage_vehicle_allowed(m.vehicle_id))
      and (p_sector_id is null or v.sector_id=p_sector_id)
      and (p_fuel_type is null or t.fuel_type=p_fuel_type)
      and (p_tank_id is null or m.tank_id=p_tank_id)
      and (p_vehicle_id is null or m.vehicle_id=p_vehicle_id)
      and (v_vehicle_ids is null or m.vehicle_id=any(v_vehicle_ids))
      and (p_movement_type is null or m.movement_type=p_movement_type)
  ) select jsonb_build_object(
    'totalCount',(select count(*) from filtered),
    'selectedVehicles',(select coalesce(jsonb_agg(to_jsonb(x) order by x."vehicleName",x."dbNumber"),'[]') from(select v.id,v.vehicle_name "vehicleName",v.db_number "dbNumber",v.driver_name "driverName",v.plate_number "plateNumber",s.name "areaName" from public.garage_vehicles v left join public.sectors s on s.id=v.sector_id where app.garage_vehicle_allowed(v.id) and (v.id=p_vehicle_id or (v_vehicle_ids is not null and v.id=any(v_vehicle_ids))))x),
    'stockInTotal',(select coalesce(sum(quantity),0) from filtered where movement_type='stock_in'),
    'consumptionTotal',(select coalesce(sum(-quantity),0) from filtered where movement_type='vehicle_fill'),
    'resetTotal',(select coalesce(sum(-quantity),0) from filtered where movement_type='approved_reset'),
    'byType',(select coalesce(jsonb_agg(to_jsonb(x) order by x.quantity desc),'[]') from(select fuel_type "fuelType",unit,sum(case when movement_type='vehicle_fill' then -quantity else 0 end) quantity from filtered group by fuel_type,unit)x),
    'byTank',(select coalesce(jsonb_agg(to_jsonb(x) order by x.consumption desc),'[]') from(select tank_id "tankId",tank_name "tankName",fuel_type "fuelType",unit,sum(case when movement_type='stock_in' then quantity else 0 end) "stockIn",sum(case when movement_type='vehicle_fill' then -quantity else 0 end) consumption from filtered group by tank_id,tank_name,fuel_type,unit)x),
    'byVehicle',(select coalesce(jsonb_agg(to_jsonb(x) order by x.quantity desc),'[]') from(select vehicle_id "vehicleId",vehicle_name "vehicleName",db_number "dbNumber",unit,sum(-quantity) quantity from filtered where movement_type='vehicle_fill' group by vehicle_id,vehicle_name,db_number,unit order by quantity desc limit 100)x),
    'byUnit',(select coalesce(jsonb_agg(to_jsonb(x) order by x.unit),'[]') from(select unit,sum(case when movement_type='stock_in' then quantity else 0 end) "stockIn",sum(case when movement_type='vehicle_fill' then -quantity else 0 end) consumption,sum(case when movement_type='approved_reset' then -quantity else 0 end) reset from filtered group by unit)x),
    'rows',(select coalesce(jsonb_agg(to_jsonb(x) order by x."createdAt" desc),'[]') from(select id,"tankId","vehicleId","movementType",quantity,"quantityBefore","quantityAfter","nextRefillDate",notes,"actorId","actorName","createdAt","tankName","fuelType",unit,"vehicleName","dbNumber","areaName","parentSector" from (select id,tank_id "tankId",vehicle_id "vehicleId",movement_type "movementType",quantity,quantity_before "quantityBefore",quantity_after "quantityAfter",next_refill_date "nextRefillDate",notes,actor_id "actorId",actor_name "actorName",created_at "createdAt",tank_name "tankName",fuel_type "fuelType",unit,vehicle_name "vehicleName",db_number "dbNumber",area_name "areaName",parent_sector "parentSector" from filtered order by created_at desc limit p_limit offset p_offset)y)x),
    'from',v_from,'to',v_to
  ) into v_result;
  return v_result;
end$$;

-- غلاف التوافق القديم يستفيد من التقرير المحمي أعلاه.
create or replace function public.garage_consumption_report(p_from date,p_to date,p_sector_id smallint,p_fuel_type text,p_tank_id uuid,p_vehicle_id uuid,p_movement_type text,p_limit integer,p_offset integer)
returns jsonb language sql stable security definer set search_path=public,app as $$select public.garage_consumption_report(p_from,p_to,p_sector_id,p_fuel_type,p_tank_id,p_vehicle_id,null::uuid[],p_movement_type,p_limit,p_offset)$$;

alter function public.maintenance_case_events(uuid)rename to maintenance_case_events_unscoped;
revoke all on function public.maintenance_case_events_unscoped(uuid)from public,anon,authenticated;
create function public.maintenance_case_events(p_case_id uuid)
returns table(event_key text,event_type text,title text,details text,happened_at timestamptz,actor_id uuid,status text,progress integer,sequence_no integer)
language plpgsql stable security definer set search_path=public,app as $$begin perform app.require_garage_case_access(p_case_id);return query select*from public.maintenance_case_events_unscoped(p_case_id);end$$;
revoke all on function public.maintenance_case_events(uuid)from public,anon;
grant execute on function public.maintenance_case_events(uuid)to authenticated;
